param([ValidateSet('init','migrate','run')][string]$Action='run')
$ErrorActionPreference='Stop'
$taskRoot=Split-Path $PSScriptRoot -Parent
$taskConfigPath=Join-Path $taskRoot 'ruoyi-admin/src/main/resources/application-druid.yml'
$taskConfig=if(Test-Path -LiteralPath $taskConfigPath){Get-Content -LiteralPath $taskConfigPath -Raw}else{''}
$taskUserRaw=if($env:HEXU_MYSQL_USER){$env:HEXU_MYSQL_USER}else{[regex]::Match($taskConfig,'(?m)^\s+username:\s*(.+)$').Groups[1].Value.Trim().Trim('"',"'")}
$taskPasswordRaw=if($env:HEXU_MYSQL_PASSWORD){$env:HEXU_MYSQL_PASSWORD}else{[regex]::Match($taskConfig,'(?m)^\s+password:\s*(.*)$').Groups[1].Value.Trim().Trim('"',"'")}
$taskUser=if($taskUserRaw -match '^\$\{[^:}]+:([^}]+)\}$'){$Matches[1]}else{$taskUserRaw}
$taskPassword=if($taskPasswordRaw -match '^\$\{[^:}]+:([^}]+)\}$'){$Matches[1]}else{$taskPasswordRaw}
$taskPort=if($env:HEXU_MYSQL_PORT){[int]$env:HEXU_MYSQL_PORT}else{3307}
if(!$taskUser -or $taskPort -lt 1 -or $taskPort -gt 65535){throw 'Set HEXU_MYSQL_USER and a valid HEXU_MYSQL_PORT.'}
$taskRuntime=Join-Path $taskRoot '.hexu-local'
New-Item -ItemType Directory -Force -Path $taskRuntime | Out-Null
function Write-TaskUtf8 {
    param([System.Diagnostics.Process]$Process,[string]$Text)
    $bytes=[System.Text.UTF8Encoding]::new($false).GetBytes($Text)
    $stream=$Process.StandardInput.BaseStream
    $stream.Write($bytes,0,$bytes.Length);$stream.Flush();$stream.Close()
}
function Add-TaskPageSchema {
    $taskSeedPath=Join-Path $taskRoot 'ruoyi-admin/src/main/resources/hexu-ui-seed.json'
    if(!(Test-Path -LiteralPath $taskSeedPath)){return}
    $taskJson=[System.IO.File]::ReadAllText($taskSeedPath,[System.Text.Encoding]::UTF8)
    # Keep the JSON valid when it is transported through a MySQL string literal.
    $taskJsonSql=$taskJson.Replace('\','\\').Replace("'","''")
    $taskPageSql="INSERT INTO hx_document(id,shop_id,member_id,kind,status,body_json,created_at,updated_at) SELECT CONCAT('PAGESCHEMA',s.id),s.id,0,'page_schema','ACTIVE','$taskJsonSql',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM hx_shop s WHERE NOT EXISTS (SELECT 1 FROM hx_document d WHERE d.shop_id=s.id AND d.kind='page_schema' AND d.status='ACTIVE');"
    $taskPageStart=[System.Diagnostics.ProcessStartInfo]::new()
    $taskPageStart.FileName=(Get-Command mysql).Source
    $taskPageStart.Arguments="-u $taskUser -h 127.0.0.1 -P $taskPort --default-character-set=utf8mb4 hexu_integration"
    $taskPageStart.UseShellExecute=$false;$taskPageStart.CreateNoWindow=$true
    $taskPageStart.RedirectStandardInput=$true
    $taskPageProcess=[System.Diagnostics.Process]::Start($taskPageStart)
    Write-TaskUtf8 $taskPageProcess $taskPageSql
    $taskPageProcess.WaitForExit()
    if($taskPageProcess.ExitCode -ne 0){throw 'Page schema seed failed.'}
}
function Publish-TaskPolicies {
    & node (Join-Path $taskRoot 'scripts/publish-policy-documents.mjs') $taskUser $taskPort
    if($LASTEXITCODE -ne 0){throw 'Policy publication failed.'}
}
if($Action -eq 'init') {
    $env:MYSQL_PWD=$taskPassword
    try {
        $taskExisting=& mysql -u $taskUser -h 127.0.0.1 -P $taskPort -N -e "SELECT COUNT(*) FROM information_schema.schemata WHERE schema_name='hexu_integration'"
        if($LASTEXITCODE -ne 0){throw 'Unable to connect to local MySQL.'}
        if([int]$taskExisting -gt 0){
            $taskTableCount=& mysql -u $taskUser -h 127.0.0.1 -P $taskPort -N -e "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='hexu_integration'"
            if([int]$taskTableCount -gt 0){throw 'hexu_integration contains data; refusing to overwrite.'}
        }
        $taskAdminHash=if($env:HEXU_ADMIN_BCRYPT_HASH){$env:HEXU_ADMIN_BCRYPT_HASH}else{Read-Host 'Paste the BCrypt hash generated by scripts/HashPassword.java for your new admin password'}
        if($taskAdminHash -notmatch '^\$2[aby]\$\d{2}\$[./A-Za-z0-9]{53}$'){throw 'A valid BCrypt hash is required; no default password is provided.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort -e 'CREATE DATABASE IF NOT EXISTS hexu_integration CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci'
        foreach($taskSql in @('sql/ruoyi-bootstrap.sql','ruoyi-admin/src/main/resources/db/hexu-schema.sql','ruoyi-admin/src/main/resources/db/hexu-seed.sql','sql/hexu-menus.sql','sql/hexu-closure-migration.sql')) {
            $taskStart=[System.Diagnostics.ProcessStartInfo]::new()
            $taskStart.FileName=(Get-Command mysql).Source
            $taskStart.Arguments="-u $taskUser -h 127.0.0.1 -P $taskPort --default-character-set=utf8mb4 hexu_integration"
            $taskStart.UseShellExecute=$false; $taskStart.CreateNoWindow=$true
            $taskStart.RedirectStandardInput=$true
            $taskProcess=[System.Diagnostics.Process]::Start($taskStart)
            $taskSqlText=[System.IO.File]::ReadAllText((Join-Path $taskRoot $taskSql),[System.Text.Encoding]::UTF8)
            Write-TaskUtf8 $taskProcess $taskSqlText.Replace('REPLACE_WITH_BCRYPT_HASH',$taskAdminHash)
            $taskProcess.WaitForExit()
            if($taskProcess.ExitCode -ne 0){throw "Failed importing $taskSql"}
        }
        # Storefront/page-schema seed is additive and must run after the core
        # document table exists.  Without this import the mini-program falls
        # back to the bundled migration canvas on a fresh local database.
        $taskUiSeedPath=Join-Path $taskRoot 'ruoyi-admin/src/main/resources/db/hexu-ui-config-migration.sql'
        if(Test-Path -LiteralPath $taskUiSeedPath){
            $taskUiStart=[System.Diagnostics.ProcessStartInfo]::new()
            $taskUiStart.FileName=(Get-Command mysql).Source
            $taskUiStart.Arguments="-u $taskUser -h 127.0.0.1 -P $taskPort --default-character-set=utf8mb4 hexu_integration"
            $taskUiStart.UseShellExecute=$false;$taskUiStart.CreateNoWindow=$true
            $taskUiStart.RedirectStandardInput=$true
            $taskUiProcess=[System.Diagnostics.Process]::Start($taskUiStart)
            Write-TaskUtf8 $taskUiProcess ([System.IO.File]::ReadAllText($taskUiSeedPath,[System.Text.Encoding]::UTF8))
            $taskUiProcess.WaitForExit()
            if($taskUiProcess.ExitCode -ne 0){throw 'Failed importing hexu-ui-config-migration.sql'}
        }
        Add-TaskPageSchema
        Publish-TaskPolicies
        Write-Output 'Created isolated hexu_integration database. Other databases were not changed.'
    } finally {Remove-Item Env:MYSQL_PWD -ErrorAction SilentlyContinue}
}
elseif($Action -eq 'migrate') {
    $env:MYSQL_PWD=$taskPassword
    try {
        foreach($taskColumn in @(@('hx_audit','actor_kind','VARCHAR(16) NOT NULL DEFAULT ''UNKNOWN'''),@('hx_audit','source','VARCHAR(16) NOT NULL DEFAULT ''UNKNOWN'''),@('hx_audit','request_id','VARCHAR(100) NOT NULL DEFAULT '''''),@('hx_audit','ip_masked','VARCHAR(80) NOT NULL DEFAULT '''''),@('hx_message','event_type','VARCHAR(32) NOT NULL DEFAULT ''SYSTEM'''),@('hx_message','body_text','TEXT'),@('hx_refund','evidence_json','TEXT'),@('hx_inventory_log','defective_delta','INT NOT NULL DEFAULT 0'),@('hx_order','shop_points_earned','BIGINT NOT NULL DEFAULT 0'),@('hx_order','cross_authorization_id','VARCHAR(64)'),@('hx_points','batches_initialized','BOOLEAN NOT NULL DEFAULT FALSE'),@('hx_document','campaign_ref','VARCHAR(64)'),@('hx_refund','return_json','TEXT'),@('hx_refund','exchange_json','TEXT'),@('hx_sku','point_price','BIGINT NOT NULL DEFAULT 0'),@('hx_earning','frozen_amount','BIGINT NOT NULL DEFAULT 0'),@('hx_order','points_scope','BIGINT NOT NULL DEFAULT 0'),@('hx_withdrawal','payout_operator','BIGINT'),@('hx_withdrawal','payout_evidence_json','TEXT'),@('hx_withdrawal','payout_reason','VARCHAR(500)'),@('hx_withdrawal','payout_recorded_at','TIMESTAMP NULL'),@('hx_order','remark','VARCHAR(800) NOT NULL DEFAULT '''''),@('hx_sku_detail','brand','VARCHAR(80) NOT NULL DEFAULT '''''))) {
            $taskCount=& mysql -u $taskUser -h 127.0.0.1 -P $taskPort -N -e "SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='hexu_integration' AND table_name='$($taskColumn[0])' AND column_name='$($taskColumn[1])'"
            if($LASTEXITCODE -ne 0){throw 'Failed inspecting integration schema.'}
            if([int]$taskCount -eq 0){& mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "ALTER TABLE $($taskColumn[0]) ADD COLUMN $($taskColumn[1]) $($taskColumn[2])";if($LASTEXITCODE -ne 0){throw 'Migration failed.'}}
        }
        $taskReceiptIndex=& mysql -u $taskUser -h 127.0.0.1 -P $taskPort -N -e "SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema='hexu_integration' AND table_name='hx_ledger' AND index_name='hx_ledger_receipt_lookup'"
        if($LASTEXITCODE -ne 0){throw 'Failed inspecting receipt lookup index.'}
        if([int]$taskReceiptIndex -eq 0){& mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE INDEX hx_ledger_receipt_lookup ON hx_ledger(reference_id,shop_id,category,id)";if($LASTEXITCODE -ne 0){throw 'Receipt lookup index migration failed.'}}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "UPDATE hx_document SET campaign_ref=JSON_UNQUOTE(JSON_EXTRACT(body_json,'$.campaignId')) WHERE kind='coupon_claim' AND campaign_ref IS NULL"
        if($LASTEXITCODE -ne 0){throw 'Coupon migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_wechat_account (app_id VARCHAR(80) NOT NULL, open_id VARCHAR(100) NOT NULL, member_id BIGINT NOT NULL, PRIMARY KEY(app_id,open_id), UNIQUE(member_id))"
        if($LASTEXITCODE -ne 0){throw 'Identity migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_attachment (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, purpose VARCHAR(24) NOT NULL, mime VARCHAR(40) NOT NULL, iv VARBINARY(12) NOT NULL, cipher_bytes LONGBLOB NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP)"
        if($LASTEXITCODE -ne 0){throw 'Attachment migration failed.'}
        foreach($taskTable in @('hx_agent','hx_shop')){
            $taskExtra=& mysql -u $taskUser -h 127.0.0.1 -P $taskPort -N -e "SELECT extra FROM information_schema.columns WHERE table_schema='hexu_integration' AND table_name='$taskTable' AND column_name='id'"
            if($taskExtra -notmatch 'auto_increment'){& mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "ALTER TABLE $taskTable MODIFY id BIGINT NOT NULL AUTO_INCREMENT";if($LASTEXITCODE -ne 0){throw 'Identifier migration failed.'}}
        }
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_marketing_usage (order_id VARCHAR(64) NOT NULL, campaign_id VARCHAR(64) NOT NULL, qty BIGINT NOT NULL, PRIMARY KEY(order_id,campaign_id))"
        if($LASTEXITCODE -ne 0){throw 'Marketing migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_channel_event (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, event_type VARCHAR(32) NOT NULL, business_id VARCHAR(64) NOT NULL, channel_ref VARCHAR(100) NOT NULL, payload_json TEXT NOT NULL, status VARCHAR(24) NOT NULL, error_message VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, processed_at TIMESTAMP NULL)"
        if($LASTEXITCODE -ne 0){throw 'Channel inbox migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_point_batch (id BIGINT PRIMARY KEY AUTO_INCREMENT, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, remaining BIGINT NOT NULL, expired BIGINT NOT NULL DEFAULT 0, reclaimed_expired BIGINT NOT NULL DEFAULT 0, expires_at TIMESTAMP NULL, origin_kind VARCHAR(32) NOT NULL, origin_ref VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX hx_batch_account(shop_id,member_id,expires_at))"
        if($LASTEXITCODE -ne 0){throw 'Point batch migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_point_use (id BIGINT PRIMARY KEY AUTO_INCREMENT, batch_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, amount BIGINT NOT NULL, restored BIGINT NOT NULL DEFAULT 0, kind VARCHAR(32) NOT NULL, reference_id VARCHAR(64) NOT NULL, INDEX hx_use_reference(shop_id,member_id,reference_id))"
        if($LASTEXITCODE -ne 0){throw 'Point batch migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_referral (shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, inviter_agent_id BIGINT NOT NULL, inviter_member_id BIGINT NOT NULL, invite_id VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(shop_id,member_id));"
        if($LASTEXITCODE -ne 0){throw 'Invitation migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_invitation_order (order_id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, campaign_id VARCHAR(64) NOT NULL, buyer_id BIGINT NOT NULL, inviter_agent_id BIGINT NOT NULL, qualifying_amount BIGINT NOT NULL, threshold_amount BIGINT NOT NULL);"
        if($LASTEXITCODE -ne 0){throw 'Invitation migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_invitation_reward (campaign_id VARCHAR(64) NOT NULL, buyer_id BIGINT NOT NULL, milestone INT NOT NULL, order_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, inviter_agent_id BIGINT NOT NULL, amount BIGINT NOT NULL, snapshot_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(campaign_id,buyer_id,milestone));"
        if($LASTEXITCODE -ne 0){throw 'Invitation migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_group_buy (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, campaign_id VARCHAR(64) NOT NULL, leader_id BIGINT NOT NULL, sku_id VARCHAR(64) NOT NULL, target_size INT NOT NULL, price BIGINT NOT NULL, status VARCHAR(24) NOT NULL, expires_at TIMESTAMP NOT NULL, formed_at TIMESTAMP NULL, snapshot_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);"
        if($LASTEXITCODE -ne 0){throw 'Group purchase migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_group_member (group_id VARCHAR(64) NOT NULL, member_id BIGINT NOT NULL, order_id VARCHAR(64) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(group_id,member_id));"
        if($LASTEXITCODE -ne 0){throw 'Group purchase migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_group_refund (refund_id VARCHAR(64) PRIMARY KEY, status VARCHAR(24) NOT NULL, attempts INT NOT NULL DEFAULT 0, next_attempt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_error VARCHAR(1000), updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);"
        if($LASTEXITCODE -ne 0){throw 'Group purchase migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_assessment_period (id VARCHAR(64) PRIMARY KEY, rule_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, agent_id BIGINT NOT NULL, member_id BIGINT NOT NULL, rank_no INT NOT NULL, period_start VARCHAR(10) NOT NULL, period_end VARCHAR(10) NOT NULL, passed BOOLEAN NOT NULL, failures INT NOT NULL, evaluation_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(rule_id,agent_id,period_start));"
        if($LASTEXITCODE -ne 0){throw 'Assessment migration failed.'}
        $hexuApprovalColumn = & mysql -u $taskUser -h 127.0.0.1 -P $taskPort -N -e "SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='hexu_integration' AND table_name='hx_agent' AND column_name='approved_at'"
        if([int]$hexuApprovalColumn -eq 0){& mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "ALTER TABLE hx_agent ADD COLUMN approved_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP";if($LASTEXITCODE -ne 0){throw 'Agent approval timestamp migration failed.'}}
        $hexuWithdrawalMerchantColumn = & mysql -u $taskUser -h 127.0.0.1 -P $taskPort -N -e "SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='hexu_integration' AND table_name='hx_withdrawal' AND column_name='merchant_no'"
        if([int]$hexuWithdrawalMerchantColumn -eq 0){& mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "ALTER TABLE hx_withdrawal ADD COLUMN merchant_no VARCHAR(80); UPDATE hx_withdrawal w JOIN hx_shop s ON s.id=w.shop_id SET w.merchant_no=s.merchant_no WHERE w.merchant_no IS NULL";if($LASTEXITCODE -ne 0){throw 'Withdrawal merchant snapshot migration failed.'}}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_reconciliation_batch (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, statement_date VARCHAR(10) NOT NULL, source VARCHAR(24) NOT NULL, content_hash VARCHAR(64) NOT NULL, total_rows INT NOT NULL, processed_rows INT NOT NULL DEFAULT 0, status VARCHAR(24) NOT NULL, created_by VARCHAR(80) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(shop_id,statement_date,content_hash));"
        if($LASTEXITCODE -ne 0){throw 'Reconciliation migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_reconciliation_line (id VARCHAR(64) PRIMARY KEY, batch_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, row_no INT NOT NULL, operation VARCHAR(24) NOT NULL, business_id VARCHAR(64) NOT NULL, channel_ref VARCHAR(100) NOT NULL, merchant_no VARCHAR(80) NOT NULL, channel_amount BIGINT NOT NULL, expected_amount BIGINT, difference BIGINT, status VARCHAR(32) NOT NULL, note VARCHAR(500), INDEX hx_reconcile_batch(batch_id,row_no));"
        if($LASTEXITCODE -ne 0){throw 'Reconciliation migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_reconciliation_adjustment (id VARCHAR(64) PRIMARY KEY, line_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, operation VARCHAR(24) NOT NULL, business_id VARCHAR(64) NOT NULL, channel_ref VARCHAR(100) NOT NULL, amount BIGINT NOT NULL, status VARCHAR(24) NOT NULL, requested_by VARCHAR(80) NOT NULL, reason VARCHAR(500) NOT NULL, evidence_json TEXT NOT NULL, reviewed_by VARCHAR(80), review_reason VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TIMESTAMP NULL, INDEX hx_adjust_business(shop_id,operation,business_id,channel_ref));"
        if($LASTEXITCODE -ne 0){throw 'Reconciliation migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_link_participant (campaign_id VARCHAR(64) NOT NULL, agent_id BIGINT NOT NULL, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, origin_parent_id BIGINT, marketing_parent_id BIGINT, role VARCHAR(16) NOT NULL, status VARCHAR(24) NOT NULL, promoted_once BOOLEAN NOT NULL DEFAULT FALSE, joined_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(campaign_id,agent_id));"
        if($LASTEXITCODE -ne 0){throw 'Link campaign migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_link_order (order_id VARCHAR(64) PRIMARY KEY, campaign_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, agent_id BIGINT NOT NULL, qualifying_amount BIGINT NOT NULL, threshold_amount BIGINT NOT NULL, is_new_agent BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX hx_link_qualify(campaign_id,agent_id));"
        if($LASTEXITCODE -ne 0){throw 'Link campaign migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_link_reward (order_id VARCHAR(64) NOT NULL, campaign_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, subject_agent_id BIGINT NOT NULL, recipient_agent_id BIGINT NOT NULL, reward_type VARCHAR(24) NOT NULL, amount BIGINT NOT NULL, snapshot_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(order_id,recipient_agent_id,reward_type), INDEX hx_link_cap(campaign_id,recipient_agent_id));"
        if($LASTEXITCODE -ne 0){throw 'Link campaign migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_sku_detail (shop_id BIGINT NOT NULL, sku_id VARCHAR(64) NOT NULL, category VARCHAR(80) NOT NULL DEFAULT '', brand VARCHAR(80) NOT NULL DEFAULT '', product_group VARCHAR(64) NOT NULL DEFAULT '', description TEXT, freight_id VARCHAR(64) NOT NULL DEFAULT '', weight_grams INT NOT NULL DEFAULT 1000, allow_loose BOOLEAN NOT NULL DEFAULT TRUE, gallery_json TEXT, retail_min BIGINT NOT NULL DEFAULT 0, retail_max BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(shop_id,sku_id));"
        if($LASTEXITCODE -ne 0){throw 'Catalog detail migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_point_risk_case (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, member_id BIGINT NOT NULL, reason VARCHAR(500) NOT NULL, status VARCHAR(24) NOT NULL, rule_json TEXT NOT NULL, reviewer VARCHAR(80), review_note VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TIMESTAMP NULL, INDEX hx_point_risk_account(shop_id,member_id,status));"
        if($LASTEXITCODE -ne 0){throw 'Point risk migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_report_job (id VARCHAR(64) PRIMARY KEY, shop_id BIGINT NOT NULL, created_by BIGINT NOT NULL, staff_actor BOOLEAN NOT NULL, platform_actor BOOLEAN NOT NULL, filters_json TEXT NOT NULL, status VARCHAR(24) NOT NULL, total_rows BIGINT NOT NULL DEFAULT 0, processed_rows BIGINT NOT NULL DEFAULT 0, cursor_id BIGINT NOT NULL DEFAULT 0, error_message VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, snapshot_at TIMESTAMP NULL, completed_at TIMESTAMP NULL);"
        if($LASTEXITCODE -ne 0){throw 'Report migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_report_line (job_id VARCHAR(64) NOT NULL, line_id BIGINT NOT NULL, order_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, shop_name VARCHAR(160), county VARCHAR(100), buyer_id BIGINT NOT NULL, buyer_name VARCHAR(160), sku_id VARCHAR(64) NOT NULL, sku_name VARCHAR(160), category VARCHAR(80), qty BIGINT NOT NULL, refunded_qty BIGINT NOT NULL, paid BIGINT NOT NULL, refunded_paid BIGINT NOT NULL, snapshot_json TEXT NOT NULL, order_status VARCHAR(24), order_type VARCHAR(24), created_at TIMESTAMP NOT NULL, business_day VARCHAR(10), cost_known BOOLEAN NOT NULL DEFAULT FALSE, agent_id BIGINT NOT NULL DEFAULT 0, agent_name VARCHAR(160), rank_no INT NOT NULL DEFAULT 0, net_cost BIGINT NOT NULL DEFAULT 0, earnings BIGINT NOT NULL DEFAULT 0, matched BOOLEAN NOT NULL DEFAULT FALSE, processed BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(job_id,line_id), INDEX hx_report_group(job_id,matched,shop_id,sku_id));"
        if($LASTEXITCODE -ne 0){throw 'Report migration failed.'}
        & mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "CREATE TABLE IF NOT EXISTS hx_report_stock (job_id VARCHAR(64) NOT NULL, shop_id BIGINT NOT NULL, sku_id VARCHAR(64) NOT NULL, sku_name VARCHAR(160), available INT NOT NULL, locked INT NOT NULL, defective INT NOT NULL, warning_qty INT NOT NULL, in_transit BIGINT NOT NULL DEFAULT 0, average_stock DECIMAL(20,4) NOT NULL DEFAULT 0, PRIMARY KEY(job_id,shop_id,sku_id));"
        if($LASTEXITCODE -ne 0){throw 'Report migration failed.'}
        $taskMenuStart=[System.Diagnostics.ProcessStartInfo]::new()
        $taskMenuStart.FileName=(Get-Command mysql).Source
        $taskMenuStart.Arguments="-u $taskUser -h 127.0.0.1 -P $taskPort --default-character-set=utf8mb4 hexu_integration"
        $taskMenuStart.UseShellExecute=$false; $taskMenuStart.CreateNoWindow=$true
        $taskMenuStart.RedirectStandardInput=$true
        $taskMenuProcess=[System.Diagnostics.Process]::Start($taskMenuStart)
        Write-TaskUtf8 $taskMenuProcess ([System.IO.File]::ReadAllText((Join-Path $taskRoot 'sql/hexu-report-menu.sql'),[System.Text.Encoding]::UTF8))
        $taskMenuProcess.WaitForExit()
        if($taskMenuProcess.ExitCode -ne 0){throw 'Report menu migration failed.'}
        $taskClosureStart=[System.Diagnostics.ProcessStartInfo]::new()
        $taskClosureStart.FileName=(Get-Command mysql).Source
        $taskClosureStart.Arguments="-u $taskUser -h 127.0.0.1 -P $taskPort --default-character-set=utf8mb4 hexu_integration"
        $taskClosureStart.UseShellExecute=$false; $taskClosureStart.CreateNoWindow=$true
        $taskClosureStart.RedirectStandardInput=$true
        $taskClosureProcess=[System.Diagnostics.Process]::Start($taskClosureStart)
        Write-TaskUtf8 $taskClosureProcess ([System.IO.File]::ReadAllText((Join-Path $taskRoot 'sql/hexu-closure-migration.sql'),[System.Text.Encoding]::UTF8))
        $taskClosureProcess.WaitForExit()
        if($taskClosureProcess.ExitCode -ne 0){throw 'V2.3 closure migration failed.'}
        $taskUiSeedPath=Join-Path $taskRoot 'ruoyi-admin/src/main/resources/db/hexu-ui-config-migration.sql'
        if(Test-Path -LiteralPath $taskUiSeedPath){
            $taskUiStart=[System.Diagnostics.ProcessStartInfo]::new()
            $taskUiStart.FileName=(Get-Command mysql).Source
            $taskUiStart.Arguments="-u $taskUser -h 127.0.0.1 -P $taskPort --default-character-set=utf8mb4 hexu_integration"
            $taskUiStart.UseShellExecute=$false;$taskUiStart.CreateNoWindow=$true
            $taskUiStart.RedirectStandardInput=$true
            $taskUiProcess=[System.Diagnostics.Process]::Start($taskUiStart)
            Write-TaskUtf8 $taskUiProcess ([System.IO.File]::ReadAllText($taskUiSeedPath,[System.Text.Encoding]::UTF8))
            $taskUiProcess.WaitForExit()
            if($taskUiProcess.ExitCode -ne 0){throw 'UI configuration migration failed.'}
        }
        Add-TaskPageSchema
        Publish-TaskPolicies
        foreach($taskMerchantColumn in @(@('subject_type','VARCHAR(24)'),@('contracted_fee_bps','INT'),@('settlement_days','INT'),@('abnormal_reason','VARCHAR(500)'))) {
            $taskMerchantCount=& mysql -u $taskUser -h 127.0.0.1 -P $taskPort -N -e "SELECT COUNT(*) FROM information_schema.columns WHERE table_schema='hexu_integration' AND table_name='hx_merchant_onboarding' AND column_name='$($taskMerchantColumn[0])'"
            if($LASTEXITCODE -ne 0){throw 'Merchant schema inspection failed.'}
            if([int]$taskMerchantCount -eq 0){& mysql -u $taskUser -h 127.0.0.1 -P $taskPort hexu_integration -e "ALTER TABLE hx_merchant_onboarding ADD COLUMN $($taskMerchantColumn[0]) $($taskMerchantColumn[1])";if($LASTEXITCODE -ne 0){throw 'Merchant migration failed.'}}
        }
        Write-Output 'Applied additive migrations to hexu_integration.'
    } finally {Remove-Item Env:MYSQL_PWD -ErrorAction SilentlyContinue}
}
else {
    $taskKeyPath=Join-Path $taskRuntime 'dev-key.txt'
    if(!(Test-Path -LiteralPath $taskKeyPath)){[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N') | Set-Content -LiteralPath $taskKeyPath -NoNewline}
    $env:HEXU_DEV_KEY=Get-Content -LiteralPath $taskKeyPath -Raw
    $env:HEXU_TOKEN_SECRET=$env:HEXU_DEV_KEY
    $taskJar=Join-Path $taskRuntime 'hexu-server.jar'
    Copy-Item -LiteralPath (Join-Path $taskRoot 'ruoyi-admin/target/ruoyi-admin.jar') -Destination $taskJar -Force
    & java '-Dfile.encoding=UTF-8' -jar $taskJar '--spring.profiles.active=druid,hexu-dev'
}
